";s:7:\"tagline\";s:47:\"Building with confidence. Delivering with care.\";s:10:\"footer_nav\";a:5:{i:0;a:2:{s:3:\"url\";s:6:\"/about\";s:5:\"label\";s:8:\"About Us\";}i:1;a:2:{s:3:\"url\";s:9:\"/services\";s:5:\"label\";s:8:\"Services\";}i:2;a:2:{s:3:\"url\";s:9:\"/projects\";s:5:\"label\";s:8:\"Projects\";}i:3;a:2:{s:3:\"url\";s:10:\"/equipment\";s:5:\"label\";s:9:\"Equipment\";}i:4;a:2:{s:3:\"url\";s:8:\"/contact\";s:5:\"label\";s:7:\"Contact\";}}s:11:\"footer_note\";s:83:\"From foundation excavation to key handover, your engineering partner at every step.\";s:12:\"company_name\";s:46:\"Al Zahraa Contracting, Construction & Building\";s:16:\"header_cta_label\";s:13:\"Free Estimate\";}}s:13:\"primary_color\";s:7:\"#102332\";s:14:\"header_cta_url\";s:8:\"/contact\";s:16:\"header_cta_label\";s:25:\"مقايسة مجانية\";s:16:\"show_demo_notice\";b:1;}}', 1790772995);

