INSERT INTO `content_items` (`id`, `kind`, `title`, `slug`, `category`, `description`, `body`, `image`, `alt`, `location`, `project_year`, `area`, `quantity`, `data`, `sort_order`, `is_published`, `is_demo`, `created_at`, `updated_at`, `translations`) VALUES
(1, 'service', 'الهيكل الخرساني والأساسات', 'concrete', 'خدمات', 'حفر وإحلال وقواعد وأعمدة وأسقف خرسانية، بتنفيذ مضبوط واختبارات جودة.', 'جسات تربة، حفر، إحلال، لبشة، قواعد منفصلة، سملات، أعمدة، فلات سلاب وسوليد سلاب، معالجة الخرسانة واختبارات المكعبات. نستخدم حديد عز وسويدي وأسمنت السويس.', 'site/3.jpeg', 'تنفيذ الأساسات والخرسانة المسلحة', NULL, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-09-26 20:47:09', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Foundation and reinforced concrete construction\", \"body\": \"Soil testing, excavation, ground improvement, raft and isolated foundations, tie beams, columns, flat slabs and solid slabs, concrete curing and cube testing.\", \"title\": \"Concrete Structures & Foundations\", \"category\": \"Construction\", \"description\": \"Excavation, soil replacement, foundations, columns and reinforced concrete slabs, delivered with careful workmanship and quality checks.\"}}'),
(2, 'service', 'التشطيبات السوبر لوكس', 'finishing', 'خدمات', 'تشطيبات داخلية راقية بتفاصيل مدروسة، من المحارة والعزل حتى التسليم على المفتاح.', 'محارة بؤج وأوتار، عزل حمامات، سيراميك وبورسلين ورخام، دهانات جوتن وGLC، جبس بورد كناوف، ألوميتال وأبواب مصفحة. تسليم على المفتاح مع تصور ثلاثي الأبعاد قبل التنفيذ.', 'site/6.jpeg', 'فني يركب بلاط بورسلين داخل مبنى', NULL, NULL, NULL, NULL, NULL, 2, 1, 0, '2026-09-26 20:47:09', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Craftsman installing porcelain floor tiles indoors\", \"body\": \"Plastering, bathroom waterproofing, ceramic, porcelain and marble, paint, gypsum board, aluminium windows and security doors. Turnkey handover with a 3D concept before work begins.\", \"title\": \"Premium Finishing\", \"category\": \"Finishing\", \"description\": \"Refined interior finishing with considered details, from plastering and waterproofing through to key handover.\"}}'),
(3, 'service', 'أعمال MEP', 'mep', 'خدمات', 'شبكات كهرباء وسباكة وتكييف وأنظمة حريق متكاملة، مع اختبارات قبل الإغلاق.', 'تصميم وتنفيذ شبكات الكهرباء والسباكة والتكييف. لوحات شنايدر، مواسير BR، كابلات السويدي، وتكييف كاريير وLG. يشمل العمل اختبار ضغط وضمان.', 'site/9.jpeg', 'تمديدات كهرباء وسباكة وتكييف', NULL, NULL, NULL, NULL, NULL, 3, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Electrical, plumbing and air conditioning installations\", \"body\": \"Design and installation of electrical, plumbing and air conditioning networks, distribution boards, pipes and cables, including pressure testing and warranty.\", \"title\": \"MEP Works\", \"category\": \"Building Systems\", \"description\": \"Integrated electrical, plumbing, air conditioning and fire protection networks, tested before concealment.\"}}'),
(4, 'service', 'المنشآت المعدنية والمصانع', 'metal', 'خدمات', 'تصميم وتوريد وتركيب الهناجر والمستودعات بهياكل فولاذية مناسبة للاستخدام.', 'تنفيذ مصانع وهناجر بمساحات حتى 5000 متر مربع، مع توريد وتركيب جمالونات بقطاعات S355 ودهان مقاوم للصدأ.', 'site/16.jpeg', 'هيكل معدني لمستودع قيد التنفيذ', NULL, NULL, NULL, NULL, NULL, 4, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Steel structure for a warehouse under construction\", \"body\": \"Industrial buildings and warehouses up to 5,000 square metres, including steel trusses and corrosion-resistant finishes.\", \"title\": \"Steel Structures & Industrial Buildings\", \"category\": \"Construction\", \"description\": \"Design, supply and installation of warehouses and industrial buildings with steel structures suited to their use.\"}}'),
(5, 'service', 'البنية التحتية والطرق', 'infrastructure', 'خدمات', 'تنفيذ أعمال الطرق والشبكات من تجهيز الموقع إلى طبقات الرصف والتسليم.', 'رصف طرق وأسفلت وبردورة وإنترلوك، وشبكات صرف ومياه وغرف تفتيش.', 'site/14.jpeg', 'معدات تنفيذ أعمال رصف الأسفلت', NULL, NULL, NULL, NULL, NULL, 5, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Equipment paving an asphalt road\", \"body\": \"Road paving, asphalt, kerbs and interlock, as well as drainage and water networks and inspection chambers.\", \"title\": \"Infrastructure & Roads\", \"category\": \"Infrastructure\", \"description\": \"Road and utility works from site preparation through paving layers and handover.\"}}'),
(6, 'service', 'اللاندسكيب والواجهات الحجرية', 'landscape', 'خدمات', 'مساحات خارجية متناسقة تجمع الحدائق والمسابح والإنارة والواجهات.', 'تصميم وتنفيذ الحدائق وحمامات السباحة والشلالات والإضاءة الخارجية والواجهات الحجرية.', 'site/1.jpeg', 'فيلا بواجهة حجرية وحديقة ومسبح', NULL, NULL, NULL, NULL, NULL, 6, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Modern villa with a stone facade, garden and pool\", \"body\": \"Design and construction of gardens, swimming pools, water features, outdoor lighting and stone facades.\", \"title\": \"Landscaping & Stone Facades\", \"category\": \"Exterior Works\", \"description\": \"Coordinated outdoor spaces combining gardens, pools, lighting and facades.\"}}'),
(7, 'project', 'فيلا عصرية – الشيخ زايد', 'villa-zayed', 'فيلا', 'نموذج تصوري لمشروع فيلا متكامل، من أعمال الهيكل والتشطيبات إلى تنسيق الموقع الخارجي.', NULL, 'site/1.jpeg', 'فيلا عصرية بواجهة حجرية وحديقة ومسبح', 'الشيخ زايد', 2024, 600, NULL, '{\"gallery\": [\"site/1.jpeg\"]}', 1, 1, 1, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Modern villa with a stone facade, garden and pool\", \"title\": \"Modern Villa — Sheikh Zayed\", \"category\": \"Villa\", \"location\": \"Sheikh Zayed\", \"description\": \"Concept design for a complete villa, from structural work and finishing to the outdoor landscape.\"}}'),
(8, 'project', 'عمارة سكنية – التجمع الخامس', 'residential-building', 'عمارة سكنية', 'نموذج تصوري لمبنى سكني متعدد الطوابق بأعمال خرسانية وواجهات حديثة.', NULL, 'site/4.jpeg', 'مبنى سكني قيد الإنشاء ورافعات', 'التجمع الخامس', 2023, 1250, NULL, '{\"gallery\": [\"site/4.jpeg\"]}', 2, 1, 1, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Residential building under construction with tower cranes\", \"title\": \"Residential Building — Fifth Settlement\", \"category\": \"Residential Building\", \"location\": \"Fifth Settlement\", \"description\": \"Concept design for a multi-storey residential building with concrete works and contemporary facades.\"}}'),
(9, 'project', 'مصنع – العبور', 'obour-factory', 'مصنع', 'نموذج تصوري لمنشأة صناعية بهيكل معدني ومساحات تشغيل مرنة.', NULL, 'site/16.jpeg', 'هيكل فولاذي لمصنع أو مستودع', 'العبور', 2024, 2000, NULL, '{\"gallery\": [\"site/16.jpeg\"]}', 3, 1, 1, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Steel structure for a factory or warehouse\", \"title\": \"Factory — Obour City\", \"category\": \"Factory\", \"location\": \"Obour City\", \"description\": \"Concept design for an industrial facility with a steel structure and flexible operating spaces.\"}}'),
(10, 'project', 'تشطيب شقة – العاصمة الإدارية', 'new-capital-finishing', 'تشطيب', 'نموذج تصوري لأعمال تشطيب شقة سكنية بمستوى سوبر لوكس.', NULL, 'site/11.jpeg', 'أعمال تشطيب داخلي للحوائط والأرضيات', 'العاصمة الإدارية', 2025, 180, NULL, '{\"gallery\": [\"site/11.jpeg\"]}', 4, 1, 1, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Interior wall and floor finishing work\", \"title\": \"Apartment Finishing — New Administrative Capital\", \"category\": \"Finishing\", \"location\": \"New Administrative Capital\", \"description\": \"Concept example of premium finishing works for a residential apartment.\"}}'),
(11, 'project', 'شبكة طرق – القاهرة الجديدة', 'road-network', 'بنية تحتية', 'نموذج تصوري لأعمال تجهيز ورصف طريق وشبكات البنية التحتية.', NULL, 'site/14.jpeg', 'أعمال رصف أسفلت في موقع طريق', 'القاهرة الجديدة', 2025, 1200, NULL, '{\"gallery\": [\"site/14.jpeg\"]}', 5, 1, 1, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Asphalt paving work on a road site\", \"title\": \"Road Network — New Cairo\", \"category\": \"Infrastructure\", \"location\": \"New Cairo\", \"description\": \"Concept example of road preparation, paving and infrastructure networks.\"}}'),
(12, 'project', 'أساسات مبنى إداري', 'foundation-works', 'هيكل خرساني', 'نموذج تصوري لأعمال حفر وتسليح وصب أساسات مبنى إداري.', NULL, 'site/13.jpeg', 'صب خرسانة مسلحة للقواعد والأساسات', 'العاصمة الإدارية', 2024, 850, NULL, '{\"gallery\": [\"site/13.jpeg\"]}', 6, 1, 1, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Reinforced concrete foundations being poured\", \"title\": \"Office Building Foundations\", \"category\": \"Concrete Structures\", \"location\": \"New Administrative Capital\", \"description\": \"Concept example of excavation, reinforcement and foundation concrete for an office building.\"}}'),
(13, 'equipment', 'حفار كات', 'excavator', NULL, 'حفارات لأعمال الحفر وتجهيز المواقع والأساسات.', NULL, 'site/3.jpeg', 'حفار كات في موقع العمل', NULL, NULL, NULL, '2 حفار', NULL, 1, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Excavator at a construction site\", \"title\": \"CAT Excavators\", \"quantity\": \"2 excavators\", \"description\": \"Excavators for earthworks, site preparation and foundations.\"}}'),
(14, 'equipment', 'لودر', 'loader', NULL, 'تحميل ونقل مواد البناء داخل مواقع التنفيذ.', NULL, 'site/12.jpeg', 'لودر في موقع العمل', NULL, NULL, NULL, '1 لودر', NULL, 2, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Construction equipment at a work site\", \"title\": \"Wheel Loader\", \"quantity\": \"1 loader\", \"description\": \"Loading and moving construction materials around the site.\"}}'),
(15, 'equipment', 'خلاطة خرسانة', 'mixer', NULL, 'خلاطات لدعم أعمال الصب والخرسانة.', NULL, 'site/8.jpeg', 'خلاطة خرسانة في موقع العمل', NULL, NULL, NULL, '3 خلاطات', NULL, 3, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Concrete being poured from a mixer truck\", \"title\": \"Concrete Mixer Trucks\", \"quantity\": \"3 mixer trucks\", \"description\": \"Mixer trucks supporting concrete placement and casting work.\"}}'),
(16, 'equipment', 'ونش برجي', 'tower-crane', NULL, 'رفع ونقل المواد للمباني متعددة الطوابق.', NULL, 'site/5.jpeg', 'ونش برجي في موقع العمل', NULL, NULL, NULL, '1 ونش برجي', NULL, 4, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Tower crane lifting materials at sunset\", \"title\": \"Tower Crane\", \"quantity\": \"1 tower crane\", \"description\": \"Lifting and moving materials on multi-storey buildings.\"}}'),
(17, 'equipment', 'سقالات', 'scaffolding', NULL, 'سقالات آمنة لأعمال الواجهات والتشطيبات المرتفعة.', NULL, 'site/2.jpeg', 'سقالات في موقع العمل', NULL, NULL, NULL, 'سقالات متعددة', NULL, 5, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Workers and engineers on construction scaffolding\", \"title\": \"Scaffolding\", \"quantity\": \"Multiple sets\", \"description\": \"Safe access for facade work and elevated finishing.\"}}'),
(18, 'equipment', 'هزازات خرسانة', 'vibrators', NULL, 'هزازات لدمك الخرسانة وتحسين تجانس الصب.', NULL, 'site/13.jpeg', 'هزازات خرسانة في موقع العمل', NULL, NULL, NULL, 'معدات متعددة', NULL, 6, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Reinforced concrete foundation work\", \"title\": \"Concrete Vibrators\", \"quantity\": \"Multiple units\", \"description\": \"Vibrators for compacting concrete and improving the consistency of each pour.\"}}'),
(19, 'equipment', 'أجهزة مساحة Total Station', 'survey', NULL, 'أجهزة مساحة وضبط مناسيب ومحاور التنفيذ.', NULL, 'site/7.jpeg', 'أجهزة مساحة Total Station في موقع العمل', NULL, NULL, NULL, 'أجهزة مساحة', NULL, 7, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"alt\": \"Engineering team reviewing a construction plan\", \"title\": \"Total Station Surveying Equipment\", \"quantity\": \"Surveying instruments\", \"description\": \"Surveying equipment for setting levels, axes and construction control points.\"}}'),
(20, 'team', 'مهندسو الهندسة المدنية', 'civil', NULL, 'يشرفون على أعمال الأساسات والهيكل والجودة الإنشائية.', NULL, 'site/7.jpeg', 'فريق هندسي وعمال في موقع تنفيذ', NULL, NULL, NULL, '3 مهندسين', NULL, 1, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Civil Engineers\", \"quantity\": \"3 engineers\", \"description\": \"Oversee foundations, structural work and construction quality.\"}}'),
(21, 'team', 'مهندسو العمارة', 'architecture', NULL, 'يتابعون التصميم المعماري وتفاصيل التنفيذ والتشطيب.', NULL, 'site/7.jpeg', 'فريق هندسي وعمال في موقع تنفيذ', NULL, NULL, NULL, '2 مهندس', NULL, 2, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Architects\", \"quantity\": \"2 architects\", \"description\": \"Coordinate architectural design, construction details and finishing.\"}}'),
(22, 'team', 'مهندسو الكهرباء', 'electrical', NULL, 'يديرون أنظمة الكهرباء والتيار الخفيف والتنسيق الفني.', NULL, 'site/7.jpeg', 'فريق هندسي وعمال في موقع تنفيذ', NULL, NULL, NULL, '2 مهندس', NULL, 3, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Electrical Engineers\", \"quantity\": \"2 engineers\", \"description\": \"Manage electrical systems, low-current networks and technical coordination.\"}}'),
(23, 'team', 'مشرفو المواقع', 'supervisors', NULL, 'يتابعون فرق التنفيذ اليومية وخطط السلامة والجودة.', NULL, 'site/7.jpeg', 'فريق هندسي وعمال في موقع تنفيذ', NULL, NULL, NULL, '5 مشرفين', NULL, 4, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Site Supervisors\", \"quantity\": \"5 supervisors\", \"description\": \"Coordinate daily site teams, safety plans and quality checks.\"}}'),
(24, 'team', 'الفنيون والعمال', 'craftspeople', NULL, 'كوادر مدربة تغطي تخصصات البناء والتشطيبات.', NULL, 'site/7.jpeg', 'فريق هندسي وعمال في موقع تنفيذ', NULL, NULL, NULL, '40+ فني وعامل', NULL, 5, 1, 0, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Skilled Tradespeople\", \"quantity\": \"40+ tradespeople\", \"description\": \"Trained teams covering construction and finishing specialties.\"}}');

