INSERT INTO `content_pages` (`id`, `title`, `slug`, `status`, `meta_title`, `meta_description`, `share_image`, `sections`, `sort_order`, `created_by`, `created_at`, `updated_at`, `translations`) VALUES
(1, 'الرئيسية', 'home', 'published', 'الرئيسية | الزهراء للمقاولات', 'الزهراء للمقاولات والتشييد والبناء – شريكك الهندسي في مصر.', NULL, '[{\"id\": \"628a6b626e\", \"alt\": \"بانر الزهراء للمقاولات والتشييد والبناء بالعربية والإنجليزية\", \"text\": \"نحوّل أرضك إلى مشروع فاخر.. بهيكل قوي، وتشطيب راقٍ، والتزام بالموعد.\", \"type\": \"hero\", \"align\": \"right\", \"image\": \"site/banner.webp\", \"title\": \"الزهراء للمقاولات والتشييد والبناء\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"primary_url\": \"/contact\", \"translations\": {\"en\": {\"alt\": \"Al Zahraa Contracting and Construction banner\", \"text\": \"We turn your land into a refined project with a strong structure, quality finishing and a clear commitment to schedule.\", \"title\": \"Al Zahraa for Contracting, Construction & Building\", \"primary_label\": \"Request a free estimate\", \"secondary_label\": \"Explore our projects\"}}, \"primary_label\": \"احصل على مقايسة مجانية\", \"secondary_url\": \"/projects\", \"image_has_text\": true, \"secondary_label\": \"شاهد مشاريعنا\"}, {\"id\": \"70cdda1e35\", \"text\": \"\", \"type\": \"stats\", \"align\": \"right\", \"image\": \"\", \"items\": [{\"label\": \"سنة خبرة\", \"value\": \"+15\", \"translations\": {\"en\": {\"label\": \"Years of experience\"}}}, {\"label\": \"مشروع تم تسليمه\", \"value\": \"+280\", \"translations\": {\"en\": {\"label\": \"Projects delivered\"}}}, {\"label\": \"عميل يثق بنا\", \"value\": \"+120\", \"translations\": {\"en\": {\"label\": \"Clients who trust us\"}}}, {\"label\": \"معدة مملوكة للشركة\", \"value\": \"50+\", \"translations\": {\"en\": {\"label\": \"Company-owned machines\"}}}], \"title\": \"أرقام تعكس خبرتنا\", \"columns\": 4, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"title\": \"Experience in Numbers\"}}}, {\"id\": \"5624960ce8\", \"text\": \"شركة الزهراء للمقاولات هي شريكك الهندسي من أول حفر الأساس لحد تسليم المفتاح. نحن لا نبني جدرانًا فقط، نحن نبني ثقة. نمتلك فريقًا هندسيًا متكاملًا ومكتبًا فنيًا ومشرفي مواقع وأسطول معدات خاصًا بنا، مما يضمن لك جودة عالية وسعرًا منافسًا دون مقاول باطن.\", \"type\": \"text-image\", \"align\": \"right\", \"image\": \"site/10.jpeg\", \"title\": \"شريكك الهندسي من أول الحفر حتى تسليم المفتاح\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"link_url\": \"/about\", \"background\": \"light\", \"link_label\": \"تعرف علينا\", \"translations\": {\"en\": {\"text\": \"Al Zahraa Contracting is your engineering partner from the first foundation excavation to key handover. We build trust as well as structures. Our integrated engineering team, technical office, site supervisors and company-owned equipment help us deliver quality and value with direct oversight.\", \"title\": \"Your engineering partner from excavation to handover\", \"link_label\": \"Get to know us\"}}}, {\"id\": \"7dce802a82\", \"text\": \"فريق واحد يدير تفاصيل مشروعك الهندسية والتنفيذية.\", \"type\": \"services\", \"align\": \"right\", \"image\": \"\", \"title\": \"خدمات متكاملة.. من الأساس إلى المفتاح\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"One team coordinates every engineering and construction detail of your project.\", \"title\": \"Complete services, from foundations to handover\"}}}, {\"id\": \"4a89666f44\", \"text\": \"خطوات واضحة تحفظ وقتك وميزانيتك.\", \"type\": \"process\", \"align\": \"right\", \"image\": \"\", \"items\": [{\"label\": \"معاينة ومقايسة مجانية\", \"value\": \"01\", \"translations\": {\"en\": {\"label\": \"Site visit and free estimate\"}}}, {\"label\": \"تصميم ومخططات تنفيذية\", \"value\": \"02\", \"translations\": {\"en\": {\"label\": \"Design and construction drawings\"}}}, {\"label\": \"تنفيذ بإشراف هندسي يومي\", \"value\": \"03\", \"translations\": {\"en\": {\"label\": \"Daily engineering supervision\"}}}, {\"label\": \"تسليم مفتاح وضمان\", \"value\": \"04\", \"translations\": {\"en\": {\"label\": \"Key handover and warranty\"}}}], \"title\": \"كيف نعمل\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Clear steps that protect your time and budget.\", \"title\": \"How We Work\"}}}, {\"id\": \"92d1bf3d91\", \"text\": \"تصور لتحول أرض فضاء إلى فيلا عصرية متكاملة.\", \"type\": \"before-after\", \"align\": \"right\", \"image\": \"site/15.jpeg\", \"title\": \"شاهد الفرق الذي نصنعه\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"alt\": \"Illustrative before and after composite of a plot transformed into a villa\", \"text\": \"A concept showing an empty plot transformed into a contemporary villa.\", \"title\": \"See the transformation we can make\"}}}, {\"id\": \"a50db89281\", \"text\": \"جودة التنفيذ تبدأ من وضوح الاتفاق وتنتهي بمتابعة ما بعد التسليم.\", \"type\": \"features\", \"align\": \"right\", \"image\": \"\", \"items\": [{\"label\": \"التزام زمني بعقد وشرط جزائي\", \"translations\": {\"en\": {\"label\": \"Schedule commitment in the contract\"}}}, {\"label\": \"إشراف مهندس مقيم يوميًا\", \"translations\": {\"en\": {\"label\": \"Daily resident engineer supervision\"}}}, {\"label\": \"مواد بفواتير وضمان\", \"translations\": {\"en\": {\"label\": \"Materials supplied with invoices and warranty\"}}}, {\"label\": \"نظام التكلفة + نسبة أو تسليم مفتاح\", \"translations\": {\"en\": {\"label\": \"Cost-plus or turnkey options\"}}}, {\"label\": \"سلامة مهنية في مواقعنا\", \"translations\": {\"en\": {\"label\": \"Professional site safety\"}}}, {\"label\": \"متابعة بعد التسليم\", \"translations\": {\"en\": {\"label\": \"Follow-up after handover\"}}}], \"title\": \"لماذا الزهراء؟\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Quality starts with a clear agreement and continues with support after handover.\", \"title\": \"Why Al Zahraa?\"}}}, {\"id\": \"13633b503e\", \"text\": \"أمثلة تصورية على أنواع الأعمال التي ننفذها.\", \"type\": \"projects\", \"align\": \"right\", \"image\": \"\", \"title\": \"نماذج من مشاريعنا\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Illustrative examples of the project types and services we offer.\", \"title\": \"Selected project concepts\"}}}, {\"id\": \"1680f56db6\", \"text\": \"اطلب معاينة ومقايسة مجانية، وسنساعدك في اختيار الخطوة الأولى.\", \"type\": \"cta\", \"align\": \"right\", \"image\": \"\", \"title\": \"جاهز تبدأ مشروعك؟\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"primary_url\": \"/contact\", \"translations\": {\"en\": {\"text\": \"Request a free site visit and estimate. We will help you choose the next step.\", \"title\": \"Ready to start your project?\", \"primary_label\": \"Start your request\"}}, \"primary_label\": \"ابدأ طلبك الآن\"}]', 0, NULL, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Home\", \"meta_title\": \"Al Zahraa Contracting | Construction & Building\", \"meta_description\": \"Al Zahraa Contracting, Construction & Building — your engineering partner in Egypt.\"}}'),
(2, 'من نحن', 'about', 'published', 'من نحن | الزهراء للمقاولات', 'الزهراء للمقاولات والتشييد والبناء – شريكك الهندسي في مصر.', NULL, '[{\"id\": \"32af690cbd\", \"text\": \"شركة الزهراء للمقاولات والتشييد والبناء.\", \"type\": \"page-hero\", \"align\": \"right\", \"image\": \"site/7.jpeg\", \"title\": \"من نحن – 15 سنة من البناء بثقة\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Al Zahraa Contracting, Construction & Building.\", \"title\": \"About Us — 15 Years of Building with Confidence\"}}}, {\"id\": \"a29a5f119c\", \"text\": \"تأسست شركة الزهراء للمقاولات والتشييد والبناء بهدف سد الفجوة بين المقاول التقليدي والشركة الهندسية المحترفة. نحن شركة مقاولات عامة مصنفة، نعمل في القاهرة الجديدة، الشيخ زايد، العاصمة الإدارية، والساحل الشمالي.\", \"type\": \"text-image\", \"align\": \"right\", \"image\": \"site/17.jpeg\", \"title\": \"نبني ثقة قبل أن نبني جدرانًا\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Al Zahraa was established to bridge the gap between traditional contracting and professional engineering. We are a general contracting company serving New Cairo, Sheikh Zayed, the New Administrative Capital and the North Coast.\", \"title\": \"We build trust before we build walls\"}}}, {\"id\": \"bbba2b856d\", \"text\": \"\", \"type\": \"values\", \"align\": \"right\", \"image\": \"\", \"items\": [{\"text\": \"أن نكون ضمن أفضل 10 شركات مقاولات في مصر بحلول 2030.\", \"title\": \"رؤيتنا\", \"translations\": {\"en\": {\"text\": \"To become one of Egypt’s leading contracting companies by 2030.\", \"title\": \"Our vision\"}}}, {\"text\": \"تقديم مشروع متكامل بأعلى جودة، بأقل هدر، وفي الوقت المحدد.\", \"title\": \"رسالتنا\", \"translations\": {\"en\": {\"text\": \"Deliver complete projects to a high standard, with less waste and on schedule.\", \"title\": \"Our mission\"}}}, {\"text\": \"الأمانة في المواد، الشفافية في التكلفة، الجودة في التنفيذ.\", \"title\": \"قيمنا\", \"translations\": {\"en\": {\"text\": \"Honest materials, transparent costs and quality workmanship.\", \"title\": \"Our values\"}}}], \"title\": \"رؤيتنا ورسالتنا وقيمنا\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"title\": \"Our Vision, Mission and Values\"}}}, {\"id\": \"4d6da8170a\", \"text\": \"كوادر متخصصة تشرف على كل مرحلة من مراحل التنفيذ.\", \"type\": \"team\", \"align\": \"right\", \"image\": \"\", \"title\": \"فريق هندسي متكامل\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Specialists oversee every stage of construction.\", \"title\": \"An Integrated Engineering Team\"}}}, {\"id\": \"8ee302c320\", \"text\": \"\", \"type\": \"gallery\", \"align\": \"right\", \"image\": \"\", \"title\": \"من قلب مواقع العمل\", \"images\": [\"site/2.jpeg\", \"site/7.jpeg\", \"site/10.jpeg\", \"site/17.jpeg\"], \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"title\": \"At the Heart of the Worksite\"}}}]', 1, NULL, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"About Us\", \"meta_title\": \"About Al Zahraa Contracting\", \"meta_description\": \"Meet Al Zahraa Contracting, Construction & Building and our engineering team.\"}}'),
(3, 'خدماتنا', 'services', 'published', 'خدماتنا | الزهراء للمقاولات', 'الزهراء للمقاولات والتشييد والبناء – شريكك الهندسي في مصر.', NULL, '[{\"id\": \"af23119a3b\", \"text\": \"حلول المقاولات والتشييد والبناء من الحفر إلى التسليم.\", \"type\": \"page-hero\", \"align\": \"right\", \"image\": \"site/8.jpeg\", \"title\": \"خدمات متكاملة لمشروع ناجح\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Contracting, construction and building solutions from excavation to handover.\", \"title\": \"Integrated Services for Successful Projects\"}}}, {\"id\": \"fc681215eb\", \"text\": \"ننسق بين التخصصات الهندسية ضمن خطة تنفيذ واضحة.\", \"type\": \"services\", \"align\": \"right\", \"image\": \"\", \"title\": \"مجالات عملنا الستة\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"We coordinate engineering disciplines within a clear construction plan.\", \"title\": \"Our Six Areas of Work\"}}}]', 2, NULL, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Our Services\", \"meta_title\": \"Construction & Engineering Services | Al Zahraa\", \"meta_description\": \"Integrated contracting, construction and building solutions from excavation through handover.\"}}'),
(4, 'مشاريعنا', 'projects', 'published', 'مشاريعنا | الزهراء للمقاولات', 'الزهراء للمقاولات والتشييد والبناء – شريكك الهندسي في مصر.', NULL, '[{\"id\": \"8f2dbba38d\", \"text\": \"نماذج تصورية للأعمال والمجالات التي تغطيها الشركة.\", \"type\": \"page-hero\", \"align\": \"right\", \"image\": \"site/4.jpeg\", \"title\": \"مشاريعنا\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Concept examples of the work and sectors covered by the company.\", \"title\": \"Our Projects\"}}}, {\"id\": \"8d46ac5cc6\", \"text\": \"جميع الصور والبيانات المعروضة للمشاريع نماذج تجريبية وليست سجلات تنفيذ موثقة.\", \"type\": \"projects\", \"align\": \"right\", \"image\": \"\", \"title\": \"معرض المشاريع\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"All project images and details shown here are illustrative concepts, not verified records of completed company work.\", \"title\": \"Project Gallery\"}}}]', 3, NULL, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Our Projects\", \"meta_title\": \"Project Portfolio | Al Zahraa Contracting\", \"meta_description\": \"Illustrative project concepts by Al Zahraa Contracting, Construction & Building.\"}}'),
(5, 'معداتنا', 'equipment', 'published', 'معداتنا | الزهراء للمقاولات', 'الزهراء للمقاولات والتشييد والبناء – شريكك الهندسي في مصر.', NULL, '[{\"id\": \"b50bbcdeef\", \"text\": \"نمتلك أسطول المعدات الذي يدعم التنفيذ ويعزز جودة العمل.\", \"type\": \"page-hero\", \"align\": \"right\", \"image\": \"site/12.jpeg\", \"title\": \"معداتنا.. جاهزية من اليوم الأول\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Our equipment fleet supports construction and helps maintain quality.\", \"title\": \"Our Equipment, Ready from Day One\"}}}, {\"id\": \"000d70335f\", \"text\": \"معداتنا وأعدادها قابلة للتحديث من لوحة الإدارة.\", \"type\": \"equipment\", \"align\": \"right\", \"image\": \"\", \"title\": \"أسطولنا المملوك\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Equipment and quantities can be updated from the administration panel.\", \"title\": \"Our Company-Owned Fleet\"}}}]', 4, NULL, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Our Equipment\", \"meta_title\": \"Construction Equipment | Al Zahraa\", \"meta_description\": \"Company-owned equipment that supports construction and quality on site.\"}}'),
(6, 'اتصل بنا', 'contact', 'published', 'اتصل بنا | الزهراء للمقاولات', 'الزهراء للمقاولات والتشييد والبناء – شريكك الهندسي في مصر.', NULL, '[{\"id\": \"ddcb3999cc\", \"text\": \"اطلب مقايسة مجانية، وفريقنا يتواصل معك لترتيب الخطوة التالية.\", \"type\": \"page-hero\", \"align\": \"right\", \"image\": \"site/5.jpeg\", \"title\": \"جاهز تبدأ مشروعك؟ كلمنا\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Request a free estimate and our team will contact you to arrange the next step.\", \"title\": \"Ready to start your project? Let’s talk\"}}}, {\"id\": \"2d5c2d3868\", \"text\": \"اكتب تفاصيل مشروعك وسنتواصل معك.\", \"type\": \"contact\", \"align\": \"right\", \"image\": \"\", \"title\": \"اطلب مقايسة مجانية\", \"columns\": 2, \"spacing\": \"normal\", \"visible\": true, \"background\": \"light\", \"translations\": {\"en\": {\"text\": \"Tell us about your project and we will be in touch.\", \"title\": \"Request a Free Estimate\"}}}]', 5, NULL, '2026-09-26 20:47:10', '2026-09-26 20:47:10', '{\"en\": {\"title\": \"Contact Us\", \"meta_title\": \"Contact Al Zahraa Contracting\", \"meta_description\": \"Request a free estimate and our team will contact you to plan the next step.\"}}');

